2. start Timer PWM and call HAL_TIM_DMABurst_WriteStart 

HAL_TIM_PWM_Start(&htim16, TIM_CHANNEL_1);
HAL_TIM_DMABurst_WriteStart(&htim16, TIM_DMABASE_ARR, TIM_DMA_UPDATE, (uint32_t *)gMotor_SRC_Buffer, TIM_DMABURSTLENGTH_3TRANSFERS);


3. in HAL_TIM_PeriodElapsedCallback call HAL_TIM_DMABurst_WriteStart again

